//! Google Calendar API v3 implementation.//!//! All API calls go through the host's HTTP capability, which handles//! credential injection and rate limiting. The WASM tool never sees//! the actual OAuth token.use crate::near::agent::host;use crate::types::*;const CALENDAR_API_BASE: &str = "https://www.googleapis.com/calendar/v3";/// Make a Google Calendar API call.fn api_call(method: &str, path: &str, body: Option<&str>) -> Result<String, String> {    let url = format!("{}/{}", CALENDAR_API_BASE, path);    let headers = if body.is_some() {        r#"{"Content-Type": "application/json"}"#    } else {        "{}"    };    let body_bytes = body.map(|b| b.as_bytes().to_vec());    host::log(        host::LogLevel::Debug,        &format!("Google Calendar API: {} {}", method, path),    );    let response = host::http_request(method, &url, headers, body_bytes.as_deref(), None)?;    if response.status < 200 || response.status >= 300 {        let body_text = String::from_utf8_lossy(&response.body);        return Err(format!(            "Google Calendar API returned status {}: {}",            response.status, body_text        ));    }    // DELETE returns no content    if response.body.is_empty() {        return Ok(String::new());    }    String::from_utf8(response.body).map_err(|e| format!("Invalid UTF-8 in response: {}", e))}/// Parse an event from the API's JSON response.fn parse_event(v: &serde_json::Value) -> Event {    Event {        id: v["id"].as_str().unwrap_or("").to_string(),        summary: v["summary"].as_str().unwrap_or("(no title)").to_string(),        description: v["description"].as_str().map(|s| s.to_string()),        location: v["location"].as_str().map(|s| s.to_string()),        start: parse_event_time(&v["start"]),        end: parse_event_time(&v["end"]),        status: v["status"].as_str().unwrap_or("confirmed").to_string(),        html_link: v["htmlLink"].as_str().map(|s| s.to_string()),        attendees: v["attendees"]            .as_array()            .map(|arr| {                arr.iter()                    .map(|a| Attendee {                        email: a["email"].as_str().unwrap_or("").to_string(),                        display_name: a["displayName"].as_str().map(|s| s.to_string()),                        response_status: a["responseStatus"].as_str().map(|s| s.to_string()),                    })                    .collect()            })            .unwrap_or_default(),        organizer: v.get("organizer").map(|o| Organizer {            email: o["email"].as_str().unwrap_or("").to_string(),            display_name: o["displayName"].as_str().map(|s| s.to_string()),        }),    }}fn parse_event_time(v: &serde_json::Value) -> EventTime {    EventTime {        date: v["date"].as_str().map(|s| s.to_string()),        date_time: v["dateTime"].as_str().map(|s| s.to_string()),        time_zone: v["timeZone"].as_str().map(|s| s.to_string()),    }}/// List events from a calendar.